#!/usr/bin/env bash
# Rewrite /etc/audit/rules.d/webshell.rules from site confs.
# never rules in audit.local.rules are placed before generated always rules.
# Every other local line is appended after the generated rules, unchanged.
# auditctl rejects -F dir= when that directory does not exist and then stops
# loading, so missing directories are left out of the generated file.
set -euo pipefail

CONFIG_ROOT="${CONFIG_ROOT:-/etc/webshell-monitor/sites}"
RULES_OUT="${RULES_OUT:-/etc/audit/rules.d/webshell.rules}"
LOCAL_RULES="${LOCAL_RULES:-/etc/webshell-monitor/audit.local.rules}"

if [ ! -d "$CONFIG_ROOT" ]; then
  echo "sync-audit: config root missing: $CONFIG_ROOT" >&2
  exit 1
fi

NOISY_RELS=(.git vendor runtime Runtime storage/framework storage/logs bootstrap/cache)

# Print the directory from a `-F dir=` field, or nothing when the line has none.
rule_dir() {
  local line=$1 dir
  case "$line" in
    *-F\ dir=*)
      dir="${line#*-F dir=}"
      printf '%s' "${dir%% *}"
      ;;
  esac
}

# Missing directories make augenrules abort the whole file at that line.
keep_rule_line() {
  local line=$1 dir
  dir="$(rule_dir "$line")"
  if [ -n "$dir" ] && [ ! -d "$dir" ]; then
    echo "sync-audit: skip missing dir: $dir" >&2
    return 1
  fi
  return 0
}

local_never_lines=()
local_other_lines=()
if [ -f "$LOCAL_RULES" ]; then
  while IFS= read -r line || [ -n "$line" ]; do
    trimmed="${line#"${line%%[![:space:]]*}"}"
    case "$trimmed" in
      -a\ never*|-A\ never*)
        keep_rule_line "$line" || continue
        local_never_lines+=("$line")
        ;;
      *)
        keep_rule_line "$line" || continue
        local_other_lines+=("$line")
        ;;
    esac
  done < "$LOCAL_RULES"
fi

exclude_rels() {
  local exclude="${1:-}"
  local token rel seen=" "
  for rel in "${NOISY_RELS[@]}"; do
    printf '%s\n' "$rel"
    seen="$seen $rel "
  done
  printf '%s' "$exclude" | tr '|' '\n' | sed -E 's/\\//g; s/^\(?//; s/\)?$//; s/^\/+//; s/\/+$//' | while IFS= read -r token || [ -n "$token" ]; do
    [ -n "$token" ] || continue
    case "$token" in
      *'*'|*'?'*|*'^'*|*'('*|*')'*|*'$'*) continue ;;
    esac
    case "$seen" in
      *" $token "*) continue ;;
    esac
    printf '%s\n' "$token"
  done
}

{
  echo "# Generated by sync_audit.sh — overwritten on install, add-site, remove-site, and GUI save."
  echo "# Put custom rules in /etc/webshell-monitor/audit.local.rules"
  if [ "${#local_never_lines[@]}" -gt 0 ]; then
    printf '%s\n' "${local_never_lines[@]}"
  fi
  shopt -s nullglob
  for conf in "$CONFIG_ROOT"/*.conf; do
    unset SITE_ID PROJECT_DIR INOTIFY_EXCLUDE || true
    # shellcheck disable=SC1090
    source "$conf"
    [ -n "${SITE_ID:-}" ] || continue
    roots=()
    watch="$CONFIG_ROOT/${SITE_ID}.watch"
    if [ -f "$watch" ]; then
      while IFS= read -r line || [ -n "$line" ]; do
        line="${line#"${line%%[![:space:]]*}"}"
        [ -z "$line" ] && continue
        [[ "$line" == \#* ]] && continue
        [[ "$line" == /* ]] && roots+=("$line")
      done < "$watch"
    fi
    if [ "${#roots[@]}" -eq 0 ] && [ -n "${PROJECT_DIR:-}" ]; then
      roots+=("$PROJECT_DIR")
    fi
    rels=()
    while IFS= read -r rel; do
      [ -n "$rel" ] && rels+=("$rel")
    done < <(exclude_rels "${INOTIFY_EXCLUDE:-}")
    for root in "${roots[@]}"; do
      root="${root%/}"
      if [ ! -d "$root" ]; then
        echo "sync-audit: skip missing dir: $root" >&2
        continue
      fi
      nevers=()
      for rel in "${rels[@]}"; do
        [ -n "$rel" ] || continue
        if [ ! -d "${root}/${rel}" ]; then
          echo "sync-audit: skip missing dir: ${root}/${rel}" >&2
          continue
        fi
        nevers+=("-a never,exit -F dir=${root}/${rel} -k webshell_exclude")
      done
      if [ "${#nevers[@]}" -gt 0 ]; then
        printf '%s\n' "${nevers[@]}" | awk '!seen[$0]++'
      fi
      echo "-a always,exit -F arch=b64 -F dir=${root} -F perm=wa -k webshell_write"
      echo "-a always,exit -F arch=b32 -F dir=${root} -F perm=wa -k webshell_write"
    done
  done
  if [ "${#local_other_lines[@]}" -gt 0 ]; then
    printf '%s\n' "${local_other_lines[@]}"
  fi
} > "$RULES_OUT.tmp"
mv "$RULES_OUT.tmp" "$RULES_OUT"

if [ "${WEBSHELL_AUDIT_DRY_RUN:-0}" = "1" ]; then
  echo "sync-audit: wrote $RULES_OUT (dry-run, not loaded)"
  exit 0
fi
if ! command -v augenrules >/dev/null 2>&1; then
  echo "sync-audit: wrote $RULES_OUT but augenrules is missing" >&2
  exit 1
fi
augenrules --load
echo "sync-audit: loaded $RULES_OUT"